  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10.63'),
  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10.630'),
