  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10.A0'),
  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10.A1'),
  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10.A2'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AA01'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AA03'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AB03')),
vsf(vs_id, system, prefix) AS (VALUES
  ('VS_ACUTE_OR_CHRONIC_PANCREATITIS', 'http://hl7.org/fhir/sid/icd-10-cm', 'K85'),
  ('VS_GLP_1_RECEPTOR_AGONIST', 'http://www.whocc.no/atc', 'A10BJ'),
  ('VS_GOUT', 'http://hl7.org/fhir/sid/icd-10-cm', 'M10'),
  ('VS_GOUT', 'http://hl7.org/fhir/sid/icd-10-cm', 'M1A'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10', 'C97'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C0'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C1'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C2'),
