  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C49'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C5'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C6'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C7'),
  ('VS_MALIGNANCY', 'http://hl7.org/fhir/sid/icd-10-cm', 'C8'),
