  ('VS_STROKE', 'http://hl7.org/fhir/sid/icd-10', 'I64'),
  ('VS_STROKE', 'http://hl7.org/fhir/sid/icd-10-cm', 'I63'),
  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10', 'E14'),
  ('VS_TYPE_1_DIABETES_MELLITUS', 'http://hl7.org/fhir/sid/icd-10-cm', 'E10'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AA'),
  ('VS_URATE_LOWERING_THERAPY', 'http://www.whocc.no/atc', 'M04AB')),
-- GZQO-INC-01 (inclusion): Male or female participants aged 18 years or older at screening.
c_gzqo_inc_01 AS (
  SELECT b.pid, b.index_date, ((date_sub('year', b.birth_date, b.index_date) >= 18)) AS v,
         concat_ws(';', NULL) AS ev
  FROM base b
  ),
a_gzqo_inc_02_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_02_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_02_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-INC-02 (inclusion): Diagnosis of gout according to the 2015 ACR/EULAR gout classification criteria.
c_gzqo_inc_02 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_inc_02_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_inc_02_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_inc_02_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_inc_02_1.ev, a_gzqo_inc_02_1_off.ev, a_gzqo_inc_02_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_02_1 ON a_gzqo_inc_02_1.pid = b.pid AND a_gzqo_inc_02_1.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_02_1_nd ON a_gzqo_inc_02_1_nd.pid = b.pid AND a_gzqo_inc_02_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_02_1_off ON a_gzqo_inc_02_1_off.pid = b.pid AND a_gzqo_inc_02_1_off.index_date = b.index_date),
a_gzqo_inc_03_1_weight AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[lb_av]' THEN o.value_num * 0.45359237 WHEN 'g' THEN o.value_num * 0.001 WHEN 'kg' THEN o.value_num * 1.0 WHEN 'lb' THEN o.value_num * 0.45359237 ELSE NULL END)) THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[lb_av]' THEN o.value_num * 0.45359237 WHEN 'g' THEN o.value_num * 0.001 WHEN 'kg' THEN o.value_num * 1.0 WHEN 'lb' THEN o.value_num * 0.45359237 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '29463-7') WHERE rn = 1),
a_gzqo_inc_03_1_height AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[in_i]' THEN o.value_num * 2.54 WHEN 'cm' THEN o.value_num * 1.0 WHEN 'in' THEN o.value_num * 2.54 WHEN 'm' THEN o.value_num * 100.0 WHEN 'mm' THEN o.value_num * 0.1 ELSE NULL END)) THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[in_i]' THEN o.value_num * 2.54 WHEN 'cm' THEN o.value_num * 1.0 WHEN 'in' THEN o.value_num * 2.54 WHEN 'm' THEN o.value_num * 100.0 WHEN 'mm' THEN o.value_num * 0.1 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '8302-2') WHERE rn = 1),
a_gzqo_inc_03_1_v AS (
  SELECT b.pid, b.index_date, weight.conv / pow(height.conv / 100.0, 2) AS val, concat_ws(';', weight.oid || '|' || strftime(weight.effective, '%Y-%m-%d'), height.oid || '|' || strftime(height.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN weight.oid IS NULL OR weight.value_num IS NULL THEN 'derived_missing_input:weight' WHEN weight.conv IS NULL THEN 'derived_unit:weight' WHEN height.oid IS NULL OR height.value_num IS NULL THEN 'derived_missing_input:height' WHEN height.conv IS NULL THEN 'derived_unit:height' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_gzqo_inc_03_1_weight weight ON weight.pid = b.pid AND weight.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_03_1_height height ON height.pid = b.pid AND height.index_date = b.index_date),
a_gzqo_inc_03_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_gzqo_inc_03_1_v),
-- GZQO-INC-03 (inclusion): Body mass index (BMI) ≥27 kg/m² at screening.
c_gzqo_inc_03 AS (
  SELECT b.pid, b.index_date, (a_gzqo_inc_03_1.val >= 27) AS v,
         concat_ws(';', a_gzqo_inc_03_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_03_1 ON a_gzqo_inc_03_1.pid = b.pid AND a_gzqo_inc_03_1.index_date = b.index_date),
a_gzqo_inc_04_1 AS (
  SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 6.8) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 6.8 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 6.8 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) IS NULL) AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERUM_URATE' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
a_gzqo_inc_04_2 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_04_2_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc))) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_04_2_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_04_3 AS (
  SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 6) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 6 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 6 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) IS NULL) AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERUM_URATE' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GZQO-INC-04 (inclusion): Serum urate ≥6.8 mg/dL at screening, or ≥6.0 mg/dL if receiving urate-lowering therapy.
c_gzqo_inc_04 AS (
  SELECT b.pid, b.index_date, (a_gzqo_inc_04_1.v OR ((CASE WHEN (coalesce(a_gzqo_inc_04_2.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_inc_04_2_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_inc_04_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AND a_gzqo_inc_04_3.v)) AS v,
         concat_ws(';', a_gzqo_inc_04_1.ev, coalesce(a_gzqo_inc_04_2.ev, a_gzqo_inc_04_2_off.ev, a_gzqo_inc_04_2_nd.ev), a_gzqo_inc_04_3.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_04_1 ON a_gzqo_inc_04_1.pid = b.pid AND a_gzqo_inc_04_1.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_04_2 ON a_gzqo_inc_04_2.pid = b.pid AND a_gzqo_inc_04_2.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_04_2_nd ON a_gzqo_inc_04_2_nd.pid = b.pid AND a_gzqo_inc_04_2_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_04_2_off ON a_gzqo_inc_04_2_off.pid = b.pid AND a_gzqo_inc_04_2_off.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_04_3 ON a_gzqo_inc_04_3.pid = b.pid AND a_gzqo_inc_04_3.index_date = b.index_date),
a_gzqo_inc_06_1_p AS (
  SELECT b.pid, b.index_date, m.mid, greatest(coalesce(m.start, m.authored), (b.index_date + -180)) AS s,
         least(coalesce(m."end", m.start, m.authored), b.index_date) AS e
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND coalesce(m.start, m.authored) IS NOT NULL
    AND greatest(coalesce(m.start, m.authored), (b.index_date + -180)) <= least(coalesce(m."end", m.start, m.authored), b.index_date)),
a_gzqo_inc_06_1_g AS (
  SELECT *, CASE WHEN s <= max(e) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) + 31 THEN 0 ELSE 1 END AS new_island
  FROM a_gzqo_inc_06_1_p),
a_gzqo_inc_06_1_i AS (
  SELECT *, sum(new_island) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS UNBOUNDED PRECEDING) AS island FROM a_gzqo_inc_06_1_g),
a_gzqo_inc_06_1 AS (
  SELECT pid, index_date, max(len) AS days, string_agg(ev, ';' ORDER BY ev) AS ev FROM (
    SELECT pid, index_date, island, (max(e) - min(s)) + 1 AS len,
           string_agg(mid, ';' ORDER BY s, mid) AS ev FROM a_gzqo_inc_06_1_i GROUP BY pid, index_date, island)
  GROUP BY pid, index_date),
a_gzqo_inc_06_1_o AS (
  SELECT b.pid, b.index_date, count(*) AS n, string_agg(m.mid, ';' ORDER BY m.mid) AS ev
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND (coalesce(m.start, m.authored) IS NULL
         OR (m."end" IS NULL AND coalesce(m.start, m.authored) <= b.index_date))
  GROUP BY b.pid, b.index_date),
-- GZQO-INC-06 (inclusion): Receiving stable urate-lowering therapy for at least 3 months (continuous within the past 6 months, gaps ≤30 days).
c_gzqo_inc_06 AS (
  SELECT b.pid, b.index_date, (CASE WHEN coalesce(a_gzqo_inc_06_1.days, 0) >= 90 THEN TRUE WHEN coalesce(a_gzqo_inc_06_1_o.n, 0) > 0 THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', (CASE WHEN coalesce(a_gzqo_inc_06_1.days, 0) >= 90 THEN a_gzqo_inc_06_1.ev WHEN coalesce(a_gzqo_inc_06_1_o.n, 0) > 0 THEN 'order_dates_missing;' || a_gzqo_inc_06_1_o.ev ELSE a_gzqo_inc_06_1.ev END)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_06_1 ON a_gzqo_inc_06_1.pid = b.pid AND a_gzqo_inc_06_1.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_06_1_o ON a_gzqo_inc_06_1_o.pid = b.pid AND a_gzqo_inc_06_1_o.index_date = b.index_date),
a_gzqo_inc_08_1_creatinine AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) > 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '2160-0') WHERE rn = 1),
a_gzqo_inc_08_1_v AS (
  SELECT b.pid, b.index_date, (CASE WHEN creatinine.conv IS NULL OR date_sub('year', b.birth_date, b.index_date) IS NULL OR (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN NULL ELSE 142.0 * pow(least(creatinine.conv / (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 0.7 ELSE 0.9 END), 1.0), (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN -0.241 ELSE -0.302 END)) * pow(greatest(creatinine.conv / (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 0.7 ELSE 0.9 END), 1.0), -1.2) * pow(0.9938, date_sub('year', b.birth_date, b.index_date)) * (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 1.012 ELSE 1.0 END) END) AS val, concat_ws(';', creatinine.oid || '|' || strftime(creatinine.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN creatinine.oid IS NULL OR creatinine.value_num IS NULL THEN 'derived_missing_input:creatinine' WHEN creatinine.conv IS NULL THEN 'derived_unit:creatinine' WHEN date_sub('year', b.birth_date, b.index_date) IS NULL THEN 'derived_missing_input:age' WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN 'derived_missing_input:sex' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_gzqo_inc_08_1_creatinine creatinine ON creatinine.pid = b.pid AND creatinine.index_date = b.index_date),
a_gzqo_inc_08_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_gzqo_inc_08_1_v),
-- GZQO-INC-08 (inclusion): Estimated GFR ≥30 mL/min/1.73 m² (CKD-EPI 2021) at screening.
c_gzqo_inc_08 AS (
  SELECT b.pid, b.index_date, (a_gzqo_inc_08_1.val >= 30) AS v,
         concat_ws(';', a_gzqo_inc_08_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_08_1 ON a_gzqo_inc_08_1.pid = b.pid AND a_gzqo_inc_08_1.index_date = b.index_date),
a_gzqo_inc_09_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, eid AS rid, start::DATE AS d FROM encounter x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOLOGY_OR_METABOLISM_CLINIC_VISIT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/department' AND vs.code = x.dept)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_inc_09_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, eid AS rid, start::DATE AS d FROM encounter x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOLOGY_OR_METABOLISM_CLINIC_VISIT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/department' AND vs.code = x.dept))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- GZQO-INC-09 (inclusion): Followed at the rheumatology or metabolism clinic with at least one visit in the past 12 months.
c_gzqo_inc_09 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_inc_09_1.n, 0) >= 1) THEN TRUE WHEN (coalesce(a_gzqo_inc_09_1.n, 0) + coalesce(a_gzqo_inc_09_1_nd.n, 0) >= 1) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_inc_09_1.ev, a_gzqo_inc_09_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_inc_09_1 ON a_gzqo_inc_09_1.pid = b.pid AND a_gzqo_inc_09_1.index_date = b.index_date
  LEFT JOIN a_gzqo_inc_09_1_nd ON a_gzqo_inc_09_1_nd.pid = b.pid AND a_gzqo_inc_09_1_nd.index_date = b.index_date),
a_gzqo_exc_01_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_01_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_01_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_1_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-01 (exclusion): Type 1 diabetes mellitus.
c_gzqo_exc_01 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_exc_01_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_01_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_01_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_01_1.ev, a_gzqo_exc_01_1_off.ev, a_gzqo_exc_01_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_01_1 ON a_gzqo_exc_01_1.pid = b.pid AND a_gzqo_exc_01_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_01_1_nd ON a_gzqo_exc_01_1_nd.pid = b.pid AND a_gzqo_exc_01_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_01_1_off ON a_gzqo_exc_01_1_off.pid = b.pid AND a_gzqo_exc_01_1_off.index_date = b.index_date),
a_gzqo_exc_02_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_02_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_02_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACUTE_OR_CHRONIC_PANCREATITIS' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-02 (exclusion): History of acute or chronic pancreatitis.
c_gzqo_exc_02 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_exc_02_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_02_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_02_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_02_1.ev, a_gzqo_exc_02_1_off.ev, a_gzqo_exc_02_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_02_1 ON a_gzqo_exc_02_1.pid = b.pid AND a_gzqo_exc_02_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_02_1_nd ON a_gzqo_exc_02_1_nd.pid = b.pid AND a_gzqo_exc_02_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_02_1_off ON a_gzqo_exc_02_1_off.pid = b.pid AND a_gzqo_exc_02_1_off.index_date = b.index_date),
a_gzqo_exc_03_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MEDULLARY_THYROID_CARCINOMA' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_03_1_nd AS (
