  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-03 (exclusion): Personal history of medullary thyroid carcinoma or multiple endocrine neoplasia type 2.
c_gzqo_exc_03 AS (
  SELECT b.pid, b.index_date, ((CASE WHEN (coalesce(a_gzqo_exc_03_1.n, 0) > 0) THEN TRUE WHEN (coalesce(a_gzqo_exc_03_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) OR (CASE WHEN (coalesce(a_gzqo_exc_03_2.n, 0) > 0) THEN TRUE WHEN (coalesce(a_gzqo_exc_03_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END)) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_03_1.ev, a_gzqo_exc_03_1_nd.ev), coalesce(a_gzqo_exc_03_2.ev, a_gzqo_exc_03_2_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_03_1 ON a_gzqo_exc_03_1.pid = b.pid AND a_gzqo_exc_03_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_03_1_nd ON a_gzqo_exc_03_1_nd.pid = b.pid AND a_gzqo_exc_03_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_03_2 ON a_gzqo_exc_03_2.pid = b.pid AND a_gzqo_exc_03_2.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_03_2_nd ON a_gzqo_exc_03_2_nd.pid = b.pid AND a_gzqo_exc_03_2_nd.index_date = b.index_date),
a_gzqo_exc_04_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_04_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc))) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_04_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GLP_1_RECEPTOR_AGONIST' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-04 (exclusion): Use of a GLP-1 receptor agonist or GIP/GLP-1 receptor agonist within 90 days before screening.
c_gzqo_exc_04 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_exc_04_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_04_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_04_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_04_1.ev, a_gzqo_exc_04_1_off.ev, a_gzqo_exc_04_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_04_1 ON a_gzqo_exc_04_1.pid = b.pid AND a_gzqo_exc_04_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_04_1_nd ON a_gzqo_exc_04_1_nd.pid = b.pid AND a_gzqo_exc_04_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_04_1_off ON a_gzqo_exc_04_1_off.pid = b.pid AND a_gzqo_exc_04_1_off.index_date = b.index_date),
a_gzqo_exc_05_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, prid AS rid, performed AS d FROM procedure x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_BARIATRIC_SURGERY' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_05_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, prid AS rid, performed AS d FROM procedure x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_BARIATRIC_SURGERY' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-05 (exclusion): Prior or planned bariatric surgery.
c_gzqo_exc_05 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_exc_05_1.n, 0) > 0) THEN TRUE WHEN (coalesce(a_gzqo_exc_05_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_05_1.ev, a_gzqo_exc_05_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_05_1 ON a_gzqo_exc_05_1.pid = b.pid AND a_gzqo_exc_05_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_05_1_nd ON a_gzqo_exc_05_1_nd.pid = b.pid AND a_gzqo_exc_05_1_nd.index_date = b.index_date),
a_gzqo_exc_06_1 AS (
  SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num > 10) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num <= 10 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num > 10 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = '%' THEN o.value_num END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = '%' THEN o.value_num END) IS NULL) AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBA1C' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GZQO-EXC-06 (exclusion): HbA1c >10% at screening.
c_gzqo_exc_06 AS (
  SELECT b.pid, b.index_date, a_gzqo_exc_06_1.v AS v,
         concat_ws(';', a_gzqo_exc_06_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_06_1 ON a_gzqo_exc_06_1.pid = b.pid AND a_gzqo_exc_06_1.index_date = b.index_date),
a_gzqo_exc_07_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -1825) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_07_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MALIGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_07_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MALIGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -1825) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-07 (exclusion): Malignancy within the past 5 years, except non-melanoma skin cancer.
c_gzqo_exc_07 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gzqo_exc_07_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_07_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_07_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_07_1.ev, a_gzqo_exc_07_1_off.ev, a_gzqo_exc_07_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_07_1 ON a_gzqo_exc_07_1.pid = b.pid AND a_gzqo_exc_07_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_07_1_nd ON a_gzqo_exc_07_1_nd.pid = b.pid AND a_gzqo_exc_07_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_07_1_off ON a_gzqo_exc_07_1_off.pid = b.pid AND a_gzqo_exc_07_1_off.index_date = b.index_date),
a_gzqo_exc_08_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -280) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_08_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_PREGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_08_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_PREGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -280) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_08_3 AS (
  SELECT pid, index_date, (o.value_code IN ('LA6576-8')) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, o.value_num AS value_num, o.value_cmp, o.value_code,
         FALSE AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -30) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY_TEST' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GZQO-EXC-08 (exclusion): Pregnant or breastfeeding, or positive pregnancy test.
c_gzqo_exc_08 AS (
  SELECT b.pid, b.index_date, ((CASE WHEN (coalesce(a_gzqo_exc_08_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_08_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_08_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) OR (((CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END)) AND a_gzqo_exc_08_3.v)) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_08_1.ev, a_gzqo_exc_08_1_off.ev, a_gzqo_exc_08_1_nd.ev), NULL, a_gzqo_exc_08_3.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_08_1 ON a_gzqo_exc_08_1.pid = b.pid AND a_gzqo_exc_08_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_08_1_nd ON a_gzqo_exc_08_1_nd.pid = b.pid AND a_gzqo_exc_08_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_08_1_off ON a_gzqo_exc_08_1_off.pid = b.pid AND a_gzqo_exc_08_1_off.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_08_3 ON a_gzqo_exc_08_3.pid = b.pid AND a_gzqo_exc_08_3.index_date = b.index_date),
a_gzqo_exc_09_1 AS (
  SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 160) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 160 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 160 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mmhg' THEN o.value_num END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mmhg' THEN o.value_num END) IS NULL) AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SYSTOLIC_BLOOD_PRESSURE' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GZQO-EXC-09 (exclusion): Uncontrolled hypertension (systolic blood pressure ≥160 mmHg) at screening.
c_gzqo_exc_09 AS (
  SELECT b.pid, b.index_date, a_gzqo_exc_09_1.v AS v,
         concat_ws(';', a_gzqo_exc_09_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_09_1 ON a_gzqo_exc_09_1.pid = b.pid AND a_gzqo_exc_09_1.index_date = b.index_date),
a_gzqo_exc_10_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_10_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_10_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MYOCARDIAL_INFARCTION' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_10_2 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_10_2_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_STROKE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gzqo_exc_10_2_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_STROKE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- GZQO-EXC-10 (exclusion): Myocardial infarction or stroke within 90 days before screening.
c_gzqo_exc_10 AS (
  SELECT b.pid, b.index_date, ((CASE WHEN (coalesce(a_gzqo_exc_10_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_10_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_10_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) OR (CASE WHEN (coalesce(a_gzqo_exc_10_2.n, 0) > 0) THEN TRUE WHEN coalesce(a_gzqo_exc_10_2_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gzqo_exc_10_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END)) AS v,
         concat_ws(';', coalesce(a_gzqo_exc_10_1.ev, a_gzqo_exc_10_1_off.ev, a_gzqo_exc_10_1_nd.ev), coalesce(a_gzqo_exc_10_2.ev, a_gzqo_exc_10_2_off.ev, a_gzqo_exc_10_2_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_10_1 ON a_gzqo_exc_10_1.pid = b.pid AND a_gzqo_exc_10_1.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_10_1_nd ON a_gzqo_exc_10_1_nd.pid = b.pid AND a_gzqo_exc_10_1_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_10_1_off ON a_gzqo_exc_10_1_off.pid = b.pid AND a_gzqo_exc_10_1_off.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_10_2 ON a_gzqo_exc_10_2.pid = b.pid AND a_gzqo_exc_10_2.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_10_2_nd ON a_gzqo_exc_10_2_nd.pid = b.pid AND a_gzqo_exc_10_2_nd.index_date = b.index_date
  LEFT JOIN a_gzqo_exc_10_2_off ON a_gzqo_exc_10_2_off.pid = b.pid AND a_gzqo_exc_10_2_off.index_date = b.index_date),
a_gzqo_exc_13_1 AS (
  SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num > 120) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num <= 120 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num > 120 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'u/l' THEN o.value_num WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mu/ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'u/ml' THEN round(o.value_num * 1000.0, 6) END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'u/l' THEN o.value_num WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mu/ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'u/ml' THEN round(o.value_num * 1000.0, 6) END) IS NULL) AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ALT' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
-- GZQO-EXC-13 (exclusion): ALT >3× upper limit of normal (>120 U/L) at screening.
c_gzqo_exc_13 AS (
  SELECT b.pid, b.index_date, a_gzqo_exc_13_1.v AS v,
         concat_ws(';', a_gzqo_exc_13_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gzqo_exc_13_1 ON a_gzqo_exc_13_1.pid = b.pid AND a_gzqo_exc_13_1.index_date = b.index_date)
SELECT b.pid, b.index_date,
  c_gzqo_inc_01.v AS "C_GZQO-INC-01", c_gzqo_inc_01.ev AS "E_GZQO-INC-01",
  c_gzqo_inc_02.v AS "C_GZQO-INC-02", c_gzqo_inc_02.ev AS "E_GZQO-INC-02",
  c_gzqo_inc_03.v AS "C_GZQO-INC-03", c_gzqo_inc_03.ev AS "E_GZQO-INC-03",
  c_gzqo_inc_04.v AS "C_GZQO-INC-04", c_gzqo_inc_04.ev AS "E_GZQO-INC-04",
  c_gzqo_inc_06.v AS "C_GZQO-INC-06", c_gzqo_inc_06.ev AS "E_GZQO-INC-06",
  c_gzqo_inc_08.v AS "C_GZQO-INC-08", c_gzqo_inc_08.ev AS "E_GZQO-INC-08",
  c_gzqo_inc_09.v AS "C_GZQO-INC-09", c_gzqo_inc_09.ev AS "E_GZQO-INC-09",
  c_gzqo_exc_01.v AS "C_GZQO-EXC-01", c_gzqo_exc_01.ev AS "E_GZQO-EXC-01",
  c_gzqo_exc_02.v AS "C_GZQO-EXC-02", c_gzqo_exc_02.ev AS "E_GZQO-EXC-02",
  c_gzqo_exc_03.v AS "C_GZQO-EXC-03", c_gzqo_exc_03.ev AS "E_GZQO-EXC-03",
  c_gzqo_exc_04.v AS "C_GZQO-EXC-04", c_gzqo_exc_04.ev AS "E_GZQO-EXC-04",
  c_gzqo_exc_05.v AS "C_GZQO-EXC-05", c_gzqo_exc_05.ev AS "E_GZQO-EXC-05",
  c_gzqo_exc_06.v AS "C_GZQO-EXC-06", c_gzqo_exc_06.ev AS "E_GZQO-EXC-06",
  c_gzqo_exc_07.v AS "C_GZQO-EXC-07", c_gzqo_exc_07.ev AS "E_GZQO-EXC-07",
  c_gzqo_exc_08.v AS "C_GZQO-EXC-08", c_gzqo_exc_08.ev AS "E_GZQO-EXC-08",
  c_gzqo_exc_09.v AS "C_GZQO-EXC-09", c_gzqo_exc_09.ev AS "E_GZQO-EXC-09",
  c_gzqo_exc_10.v AS "C_GZQO-EXC-10", c_gzqo_exc_10.ev AS "E_GZQO-EXC-10",
  c_gzqo_exc_13.v AS "C_GZQO-EXC-13", c_gzqo_exc_13.ev AS "E_GZQO-EXC-13"
FROM base b
LEFT JOIN c_gzqo_inc_01 ON c_gzqo_inc_01.pid = b.pid AND c_gzqo_inc_01.index_date = b.index_date
LEFT JOIN c_gzqo_inc_02 ON c_gzqo_inc_02.pid = b.pid AND c_gzqo_inc_02.index_date = b.index_date
LEFT JOIN c_gzqo_inc_03 ON c_gzqo_inc_03.pid = b.pid AND c_gzqo_inc_03.index_date = b.index_date
LEFT JOIN c_gzqo_inc_04 ON c_gzqo_inc_04.pid = b.pid AND c_gzqo_inc_04.index_date = b.index_date
LEFT JOIN c_gzqo_inc_06 ON c_gzqo_inc_06.pid = b.pid AND c_gzqo_inc_06.index_date = b.index_date
LEFT JOIN c_gzqo_inc_08 ON c_gzqo_inc_08.pid = b.pid AND c_gzqo_inc_08.index_date = b.index_date
LEFT JOIN c_gzqo_inc_09 ON c_gzqo_inc_09.pid = b.pid AND c_gzqo_inc_09.index_date = b.index_date
LEFT JOIN c_gzqo_exc_01 ON c_gzqo_exc_01.pid = b.pid AND c_gzqo_exc_01.index_date = b.index_date
LEFT JOIN c_gzqo_exc_02 ON c_gzqo_exc_02.pid = b.pid AND c_gzqo_exc_02.index_date = b.index_date
LEFT JOIN c_gzqo_exc_03 ON c_gzqo_exc_03.pid = b.pid AND c_gzqo_exc_03.index_date = b.index_date
LEFT JOIN c_gzqo_exc_04 ON c_gzqo_exc_04.pid = b.pid AND c_gzqo_exc_04.index_date = b.index_date
LEFT JOIN c_gzqo_exc_05 ON c_gzqo_exc_05.pid = b.pid AND c_gzqo_exc_05.index_date = b.index_date
LEFT JOIN c_gzqo_exc_06 ON c_gzqo_exc_06.pid = b.pid AND c_gzqo_exc_06.index_date = b.index_date
LEFT JOIN c_gzqo_exc_07 ON c_gzqo_exc_07.pid = b.pid AND c_gzqo_exc_07.index_date = b.index_date
LEFT JOIN c_gzqo_exc_08 ON c_gzqo_exc_08.pid = b.pid AND c_gzqo_exc_08.index_date = b.index_date
LEFT JOIN c_gzqo_exc_09 ON c_gzqo_exc_09.pid = b.pid AND c_gzqo_exc_09.index_date = b.index_date
LEFT JOIN c_gzqo_exc_10 ON c_gzqo_exc_10.pid = b.pid AND c_gzqo_exc_10.index_date = b.index_date
LEFT JOIN c_gzqo_exc_13 ON c_gzqo_exc_13.pid = b.pid AND c_gzqo_exc_13.index_date = b.index_date
ORDER BY b.pid, b.index_date
